    b.h('i. Leaving the crease', 'i۔ کریز سے نکلنا', 'i. له کریز وتل')
    P(b, [('The batsman fails in the attempt to play the ball and the wicket keeper, catching the ball, hits the wickets. If during this the batsman is outside the crease, he becomes out. This is also called stumped out.', 'بیٹسمین بال کو کھیلنے کی کوشش میں ناکام ہوا اور وکٹ کیپر بال کو پکڑ کر وکٹوں کو مار دے۔ اگر اس دوران بیٹسمین کریز سے باہر ہو تو وہ آؤٹ ہو جاتا ہے۔ اسے سٹمپ آؤٹ بھی کہتے ہیں۔', 'بیټسمن د توپ په لوبولو کې ناکام شي او ویکټ کیپر توپ ونیسي او ویکټونه ووهي. که په دې وخت کې بیټسمن له کریز بهر وي، اوټ کېږي. دې ته سټمپ اوټ هم ویل کېږي.')])
    b.h('ii. Bowled', 'ii۔ بولڈ (Bold)', 'ii. بولډ (Bold)')
    P(b, [('While playing the ball, the ball touches the wickets, or touching the batsman’s body comes and strikes the wickets, then the batsman becomes out. Being out in this way is called “bowled”.', 'گیند کو کھیلنے کے دوران گیند وکٹوں کو ٹچ کرے یا بیٹسمین کے جسم کے ساتھ ٹچ ہو کر وکٹوں کو آ کر لگے تو بیٹسمین آؤٹ ہو جاتا ہے۔ اس طرح آؤٹ ہونے کو ”بولڈ“ کہتے ہیں۔', 'د توپ د لوبولو پر مهال توپ ویکټونه ولمسوي یا د بیټسمن له بدن سره ولګېږي او راشي ویکټونو ته ولګېږي، بیټسمن اوټ کېږي. دې ډول اوټ کېدو ته "بولډ" ویل کېږي.')])
    b.h('iii. Catch out', 'iii۔ کیچ آؤٹ (Catch out)', 'iii. کیچ اوټ (Catch out)')
